with flattened_attrs as (select id, plan, currency, tier_limits, slice(tier_limits, 1, 2) as first_two_limits, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, aggregate(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, element_at(tier_prices, 1) as entry_price from price_tiers where currency in ('EUR', 'THB')) select *, lag(avg_tier_price, 1) over (order by avg_tier_price, id) as prev_avg_tier_price, min(avg_tier_price) over (partition by plan, currency) as plan_min_avg_tier_price, row_number() over (order by avg_tier_price, id) as seq_no, percent_rank() over (partition by plan order by entry_price desc) as entry_price_percent_rank, sum(entry_price) over (order by avg_tier_price, id rows between unbounded preceding and current row) as cumulative_entry_price from flattened_attrs
